<?php
declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('wedding_vows.view');$conn->set_charset('utf8mb4');$q=cb_clean($_GET['q']??'');$status=cb_clean($_GET['status']??'');$ceremony=cb_clean($_GET['ceremony']??'');$from=cb_clean($_GET['from']??'');$to=cb_clean($_GET['to']??'');$where=['1=1'];$types='';$params=[];if($q!==''){$where[]="(groom_name LIKE ? OR bride_name LIKE ? OR register_no LIKE ? OR certificate_no LIKE ?)";$like="%{$q}%";for($i=0;$i<4;$i++){$params[]=$like;$types.='s';}}if(in_array($status,['Scheduled','Banns','Solemnized','Postponed','Cancelled'],true)){$where[]='status=?';$params[]=$status;$types.='s';}if(in_array($ceremony,['Banns','Licence','Special Licence','Other'],true)){$where[]='ceremony_type=?';$params[]=$ceremony;$types.='s';}if($from!==''&&cb_valid_date($from)){$where[]='wedding_date>=?';$params[]=$from;$types.='s';}if($to!==''&&cb_valid_date($to)){$where[]='wedding_date<=?';$params[]=$to;$types.='s';}$rows=cb_fetch_all($conn,"SELECT * FROM wedding_vows WHERE ".implode(' AND ',$where)." ORDER BY wedding_date ASC,id ASC",$types,$params);$site=cb_site_setting($conn,'site_name','Church Management System');
?><!doctype html><html><head><meta charset="utf-8"><title>Wedding Vows Book</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1,h2,p{text-align:center;margin:4px}.meta{margin:15px 0;font-size:12px}table{width:100%;border-collapse:collapse;font-size:9px}th,td{border:1px solid #555;padding:5px;vertical-align:top}th{background:#eee}.actions{text-align:right;margin-bottom:15px}@media print{.actions{display:none}body{margin:8mm}}</style></head><body><div class="actions"><button onclick="window.print()">Print</button></div><h2><?= cb_h($site) ?></h2><h1>Wedding Vows Book</h1><p>Printed <?= date('d M Y, H:i') ?></p><div class="meta">Records: <?= count($rows) ?></div><table><thead><tr><th>#</th><th>Reg. No.</th><th>Date</th><th>Groom</th><th>Bride</th><th>Banns / Licence</th><th>Witnesses</th><th>Officiant</th><th>Certificate</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?= $i+1 ?></td><td><?= cb_h($r['register_no']) ?></td><td><?= cb_h($r['wedding_date']) ?></td><td><strong><?= cb_h($r['groom_name']) ?></strong><br><?= cb_h($r['groom_address']) ?></td><td><strong><?= cb_h($r['bride_name']) ?></strong><br><?= cb_h($r['bride_address']) ?></td><td><?= cb_h($r['ceremony_type']) ?><br><?= cb_h($r['marriage_licence_no']) ?></td><td><?= cb_h($r['witness_1']) ?><br><?= cb_h($r['witness_2']) ?></td><td><?= cb_h($r['officiant']) ?></td><td><?= cb_h($r['certificate_no']) ?></td><td><?= cb_h($r['status']) ?></td></tr><?php endforeach;?></tbody></table></body></html>
